import React, { useState } from 'react';
import { FileUploader } from './components/FileUploader';
import { DatasetInfo } from './components/DatasetInfo';
import { SinglePrediction } from './components/SinglePrediction';
import { DetectionSummary } from './components/DetectionSummary';
import { AttackBreakdown } from './components/AttackBreakdown';
import { BinaryMetrics } from './components/BinaryMetrics';
import { MetricsExplainer } from './components/MetricsExplainer';
import './App.css';

function App() {
  const [predictions, setPredictions] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');
  const [activeSidebar, setActiveSidebar] = useState('dashboard');

  const handleFileProcess = (data) => {
    setPredictions(data);
    setActiveTab('overview');
  };

  const handleDownload = () => {
    if (predictions?.download_url) {
      const link = document.createElement('a');
      link.href = predictions.download_url;
      link.download = 'ids_predictions.csv';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  const handleSidebarClick = (section) => {
    setActiveSidebar(section);
  };

  return (
    <div className="app-container">
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-left">
          <div className="navbar-logo">IDS</div>
          <h2>Intrusion Detection System</h2>
          <span className="navbar-status">
            <span className="status-dot"></span>
            LIVE
          </span>
        </div>
        <div className="navbar-right">
          <div className="navbar-icon" title="System Status">⚡</div>
          <div className="navbar-icon" title="Notifications">🔔</div>
          <div className="navbar-icon" title="Settings">⚙</div>
        </div>
      </nav>

      <div className="dashboard-layout">
        {/* Sidebar */}
        <aside className="sidebar">
          <div className="sidebar-section">
            <div className="sidebar-title">Menu</div>
            <button
              className={`sidebar-link ${activeSidebar === 'dashboard' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('dashboard')}
            >
              <span className="sidebar-icon">📊</span>
              <span>Dashboard</span>
            </button>
            <button
              className={`sidebar-link ${activeSidebar === 'monitor' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('monitor')}
            >
              <span className="sidebar-icon">👁</span>
              <span>Live Monitor</span>
            </button>
            <button
              className={`sidebar-link ${activeSidebar === 'threats' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('threats')}
            >
              <span className="sidebar-icon">⚠</span>
              <span>Threats</span>
              {predictions && <span className="sidebar-badge">Active</span>}
            </button>
          </div>

          <div className="sidebar-section">
            <div className="sidebar-title">Analysis</div>
            <button
              className={`sidebar-link ${activeSidebar === 'analytics' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('analytics')}
            >
              <span className="sidebar-icon">📈</span>
              <span>Analytics</span>
            </button>
            <button
              className={`sidebar-link ${activeSidebar === 'history' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('history')}
            >
              <span className="sidebar-icon">📜</span>
              <span>History</span>
            </button>
          </div>

          <div className="sidebar-section">
            <div className="sidebar-title">System</div>
            <button
              className={`sidebar-link ${activeSidebar === 'settings' ? 'active' : ''}`}
              onClick={() => handleSidebarClick('settings')}
            >
              <span className="sidebar-icon">⚙</span>
              <span>Settings</span>
            </button>
          </div>
        </aside>

        {/* Main Content */}
        <main className="main-container">
          {/* Header */}
          <div className="header-section">
            <h1>Cybersecurity Threat Dashboard</h1>
            <p>Real-time network monitoring and threat detection system. Monitor traffic, identify threats, and take defensive actions.</p>
          </div>

          {/* Dataset Info - Always Visible */}
          <DatasetInfo />

          {/* File Uploader */}
          <FileUploader onFileProcess={handleFileProcess} />

          {/* Tabs */}
          {predictions && (
            <div className="tabs">
              <div 
                className={`tab ${activeTab === 'overview' ? 'active' : ''}`}
                onClick={() => setActiveTab('overview')}
                role="button"
                tabIndex="0"
                onKeyDown={(e) => e.key === 'Enter' && setActiveTab('overview')}
              >
                <span className="tab-icon">📊</span>
                Overview
              </div>
              <div 
                className={`tab ${activeTab === 'threats' ? 'active' : ''}`}
                onClick={() => setActiveTab('threats')}
                role="button"
                tabIndex="0"
                onKeyDown={(e) => e.key === 'Enter' && setActiveTab('threats')}
              >
                <span className="tab-icon">⚠</span>
                Threats
              </div>
              {predictions.metrics && (
                <div 
                  className={`tab ${activeTab === 'metrics' ? 'active' : ''}`}
                  onClick={() => setActiveTab('metrics')}
                  role="button"
                  tabIndex="0"
                  onKeyDown={(e) => e.key === 'Enter' && setActiveTab('metrics')}
                >
                  <span className="tab-icon">📈</span>
                  Metrics
                </div>
              )}
            </div>
          )}

          {/* Content Sections */}
          {predictions && (
            <>
              {/* Overview Tab */}
              {activeTab === 'overview' && (
                <div className="tab-content">
                  {predictions.single ? (
                    <SinglePrediction
                      prediction={predictions.pred_type}
                      probability={predictions.prob_attack}
                      topClasses={predictions.top_classes}
                    />
                  ) : (
                    <>
                      <DetectionSummary stats={predictions.stats} />
                      <AttackBreakdown attackCounts={predictions.attack_counts} />
                    </>
                  )}
                </div>
              )}

              {/* Threats Tab */}
              {activeTab === 'threats' && (
                <div className="tab-content">
                  {predictions.single ? (
                    <SinglePrediction
                      prediction={predictions.pred_type}
                      probability={predictions.prob_attack}
                      topClasses={predictions.top_classes}
                    />
                  ) : (
                    <AttackBreakdown attackCounts={predictions.attack_counts} />
                  )}
                </div>
              )}

              {/* Metrics Tab */}
              {activeTab === 'metrics' && predictions.metrics && (
                <div className="tab-content">
                  <BinaryMetrics
                    metrics={predictions.metrics}
                    confusion={predictions.confusion}
                  />
                  <MetricsExplainer />
                </div>
              )}

              {/* Download Section */}
              <div className="card download-card">
                <div className="download-header">
                  <h3>Export Results</h3>
                  <p className="download-subtitle">Download predictions in CSV format</p>
                </div>
                <button 
                  onClick={handleDownload}
                  className="btn-download"
                  type="button"
                >
                  <span className="btn-icon">↓</span>
                  Download CSV
                </button>
              </div>
            </>
          )}
        </main>
      </div>
    </div>
  );
}

export default App;
